using Newtonsoft.Json;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using UnityEngine;

namespace MJ.AssetFrameWork.ABFrame
{

    public class BundleItem
    {
        //文件加载路径
        public string path;

        //文件加载路径crc
        public uint crc;

        //assetbundel名字
        public string bundleName;

        //资源名
        public string assetName;

        //assetbundle所处模块
        public BundleModuleEnum bundleModuleType;

        //assetbundel依赖
        public List<string> bundleDependce;

        //assetbundle
        public AssetBundle assetBundle;

        //通过assetbundle加载出来的对象
        public UnityEngine.Object obj;
    }


    /// <summary>
    /// AssetBudle 缓存
    /// </summary>
    public class AssetBundleCache
    {
        public AssetBundle assetBundle;
        //引用计数
        public int refereaceCount;


        public void Release(bool unLoad)
        {
            assetBundle.Unload(unLoad);
            assetBundle = null;
            refereaceCount = 0;
        }


    }
    public class AssetBundleManager
    {
        private static AssetBundleManager isntance = new AssetBundleManager();
        public static AssetBundleManager Instance => isntance;

        //已经加载的资源模块
        private List<BundleModuleEnum> mAlreadyLoadBundleModuleLsit = new List<BundleModuleEnum>();
        //ab包配置文件加载路径
        private string mBundleConfigPath;
        //ab包配置文件名称
        private string mBundleConfigName;
        //ab包配置文件名称无后缀
        private string mAssetBundleConfigName;
        //所有模块的assetbundle的资源对象字典
        //key crc
        //value BundleItem
        private Dictionary<uint, BundleItem> mAllBundleAssetDic = new Dictionary<uint, BundleItem>();
        //已经加载过的资源对象字典
        //key bundleName 
        //value asserbundleCache
        private Dictionary<string, AssetBundleCache> mAllAlreadAssetBundleDic = new Dictionary<string, AssetBundleCache>();
        //创建一个assetbundleCache类的对象池
        public ClassObjectPool<AssetBundleCache> mAssetBundleCachePool = new ClassObjectPool<AssetBundleCache>(200);

        /// <summary>
        /// 生成AssetBundleConfig配置文件路径
        /// </summary>
        /// <param name="bundleModule"></param>
        /// <returns></returns>
        public bool GeneratorBundleConfigPath(BundleModuleEnum bundleModule)
        {
            mBundleConfigName = bundleModule.ToString().ToLower() + "bundleconfig" + BundleSettings.Instance.BundlePostfix;
            mAssetBundleConfigName = bundleModule.ToString().ToLower() + "bundleconfig";
            mBundleConfigPath = BundleSettings.Instance.GetHotAssetsPath(bundleModule) + mBundleConfigName;

            //如果配置文件不存在 可能为内嵌文件解压至内嵌解压文件路径中
            if (!File.Exists(mBundleConfigPath))
            {
                mBundleConfigPath = BundleSettings.Instance.GetAssetsDeCompressPath(bundleModule);
                //如果两个地方都不存在 说明用户没有下载成功
                if (!File.Exists(mBundleConfigPath))
                    return false;
            }
            return true;
        }

        /// <summary>
        /// 加载assetsBundle配置文件
        /// </summary>
        /// <param name="bundleModuleEnum"></param>
        public void LoadAssetBundelConfig(BundleModuleEnum bundleModule)
        {
            try
            {
                if (mAlreadyLoadBundleModuleLsit.Contains(bundleModule))
                {
                    Debug.LogError("改模块资源已经加载过了不需要重复加载：" + bundleModule);
                    return;
                }

                //获取当前模块配置文件所在路径
                if (GeneratorBundleConfigPath(bundleModule))
                {
                    //if (File.Exists(mBundleConfigPath))
                    //    return;
                    AssetBundle bundleConfig = null;
                    //如果该AssetBundle 加密则需要进行解密
                    if (BundleSettings.Instance.bundleEnctypt.isEncrypt)
                        bundleConfig = AssetBundle.LoadFromMemory(AES.AESFileByteDecrypt(mBundleConfigPath, BundleSettings.Instance.bundleEnctypt.encryptKey));
                    else
                        bundleConfig = AssetBundle.LoadFromFile(mBundleConfigPath);

                    string bundleConfigJson = bundleConfig.LoadAsset<TextAsset>(mAssetBundleConfigName).text;
                    BundleConfig bundleManifeset = JsonConvert.DeserializeObject<BundleConfig>(bundleConfigJson);

                    //将所有assetbundle信息存放在字典中进行管理
                    foreach (var info in bundleManifeset.bundleInfoList)
                    {
                        if (!mAllBundleAssetDic.ContainsKey(info.crc))
                        {
                            BundleItem item = new BundleItem();
                            item.path = info.path;
                            item.crc = info.crc;
                            item.bundleModuleType = bundleModule;
                            item.assetName = info.assetName;
                            item.bundleDependce = info.bundleDependce;
                            item.bundleName = info.bundleName;
                            mAllBundleAssetDic.Add(item.crc, item);
                        }
                        else
                        {
                            //Debug.Log("AssetBundle Already Exists! BundleName:" + info.bundleName);
                        }
                    }
                    if (mAlreadyLoadBundleModuleLsit.Contains(bundleModule))
                        mAlreadyLoadBundleModuleLsit.Add(bundleModule);
                    //释放这个assetBundle配置
                    bundleConfig.Unload(false);
                    Debug.Log("模块配置文件加载完成：" + bundleModule);
                }
                else
                {
                    Debug.LogError("AssetBundleConfig Not Find. Load AssetBundel Failed! BundleModule:" + bundleModule);
                }
            }
            catch (System.Exception e)
            {
                Debug.LogError("Load AssetBundleConfig Failed,Exception:" + e.Message);
            }
        }

        /// <summary>
        /// 根据assetbundle名称 查询该assetbundle中有哪些资源
        /// </summary>
        /// <param name="bundleName"></param>
        /// <returns></returns>
        public List<BundleItem> GetBundleItemByAbName(string bundleName)
        {
            List<BundleItem> itemList = new List<BundleItem>();
            foreach (var item in mAllBundleAssetDic.Values)
            {
                if (string.Equals(item.bundleName, bundleName))
                {
                    itemList.Add(item);
                }
            }
            return itemList;
        }

        /// <summary>
        /// 通过资源路径中的crc加载该资源所在的AssetBundle
        /// </summary>
        /// <param name="crc"></param>
        /// <returns></returns>
        public BundleItem LoadAssetBundle(uint crc)
        {
            BundleItem item = null;
            //先在资源字典中查询是否存在该资源
            //如果存在说明该资源已经被打包成assetBundel
            //可以直接加载
            if (mAllBundleAssetDic.TryGetValue(crc, out item))
            {
                //如果assetBundle为空，说明该资源所在的assetbundle没有加载进内存
                if (item.assetBundle == null)
                {
                    //加载该assetbundel
                    item.assetBundle = LoadAssetBundle(item.bundleName, item.bundleModuleType);
                    //需要加载该ab包的依赖项
                    foreach (var bundleName in item.bundleDependce)
                    {
                        if (item.bundleName != bundleName)
                            LoadAssetBundle(bundleName, item.bundleModuleType);
                    }
                    return item;
                }
                else
                {
                    return item;
                }
            }
            else
            {
                //不存在说明没该资源没被打包
                Debug.LogError("Asset not exists AssetBundleConfig Load Failed! crc:" + crc);
                return null;
            }
        }

        /// <summary>
        /// 通过AssetbundleName加载AssetBundle
        /// </summary>
        /// <param name="bundleName"></param>
        /// <param name="bundleModuleEnum"></param>
        /// <returns></returns>
        public AssetBundle LoadAssetBundle(string bundleName, BundleModuleEnum bundleModuleEnum)
        {
            AssetBundleCache bundle = null;
            mAllAlreadAssetBundleDic.TryGetValue(bundleName, out bundle);
            if (bundle == null || (bundle != null && bundle.assetBundle == null))
            {
                //从类对象池中取出一个AssetBundleCache
                bundle = mAssetBundleCachePool.Spawn();
                string hotFilePath = BundleSettings.Instance.GetHotAssetsPath(bundleModuleEnum) + bundleName;
                HotAssetsModule module = MJAssetsABFrame.GetHotAssetsModule(bundleModuleEnum);
                //是否使用的是热更路径
                bool isHotPath = module == null ? (File.Exists(hotFilePath) ? true : false) : (module.HotAssetCount == 0 ? (File.Exists(hotFilePath) ? true : false) : module.HotAssetsIsExists(bundleName));
                //通过是否是热更路径计算出AssetBundle加载路径
                string bundlePath = isHotPath ? hotFilePath : BundleSettings.Instance.GetAssetsDeCompressPath(bundleModuleEnum) + bundleName;

                //判断assetbundle是否加密
                if (BundleSettings.Instance.bundleEnctypt.isEncrypt)
                {
                    byte[] bytes = AES.AESFileByteDecrypt(bundlePath, BundleSettings.Instance.bundleEnctypt.encryptKey);
                    bundle.assetBundle = AssetBundle.LoadFromMemory(bytes);
                }
                else
                {
                    //通过FromFile加载速度最快
                    bundle.assetBundle = AssetBundle.LoadFromFile(bundlePath);
                }
                if (bundle.assetBundle == null)
                {
                    Debug.LogError("Load AssetBundle Failed bundlePath :" + bundlePath);
                    return null;
                }
                bundle.refereaceCount++;
                mAllAlreadAssetBundleDic.Add(bundleName, bundle);
            }
            else
                bundle.refereaceCount++;
            return bundle.assetBundle;
        }

        /// <summary>
        /// 释放AssetBundle 并且释放AssetBundle所占用资源
        /// </summary>
        /// <param name="assetItem"></param>
        /// <param name="unLoad"></param>
        public void ReleaseAssets(BundleItem assetItem, bool unLoad)
        {
            if (assetItem != null)
            {
                assetItem.obj = null;
                ReleaseAssetBundle(assetItem, unLoad);
                if (assetItem.bundleDependce != null)
                {
                    foreach (var bundleName in assetItem.bundleDependce)
                    {
                        ReleaseAssetBundle(null, unLoad, bundleName);
                    }
                }

            }
            else
            {
                Debug.LogError("AssetItem is null, release Assets failed!");
            }
        }

        /// <summary>
        /// 释放AssetBundle及所占用资源
        /// </summary>
        /// <param name="assetItem"></param>
        /// <param name="unLoad"></param>
        /// <param name="bundleName"></param>
        public void ReleaseAssetBundle(BundleItem assetItem, bool unLoad, string bundleName = "")
        {
            string assetBundleName = "";
            if (assetItem == null)
                assetBundleName = bundleName;
            else
                assetBundleName = assetItem.bundleName;

            //AssetBundle释放
            AssetBundleCache bundleCacheItem = null;
            //如果已经加载过，并且名字不为空 就去释放他
            if (!string.IsNullOrEmpty(assetBundleName) && mAllAlreadAssetBundleDic.TryGetValue(assetBundleName, out bundleCacheItem))
            {
                if (bundleCacheItem.assetBundle != null)
                {
                    bundleCacheItem.refereaceCount--;
                    //小于等于0说明资源没有被引用可以直接释放
                    if (bundleCacheItem.refereaceCount <= 0)
                    {
                        //从已经加载过的资源对象字典中移除
                        mAllAlreadAssetBundleDic.Remove(assetBundleName);
                        bundleCacheItem.Release(unLoad);
                        //回收对象
                        mAssetBundleCachePool.Recycl(bundleCacheItem);
                    }
                }
                else
                {
                    Debug.LogError("ReleaseAssetBundle Failed, bundleCacheItem.assetBundle is Null");
                }
            }
            else
            {
                Debug.LogError("ReleaseAssetBundle Failed,BundleName is Null or bundleCacheItem is Null!\r\nAssetBundleName：" + assetBundleName);
            }
        }
    }
}

using Cysharp.Threading.Tasks;
using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Threading.Tasks;
using Unity.VisualScripting;
using UnityEngine;
using UnityEngine.U2D;
using UnityEngine.UI;

namespace MJ.AssetFrameWork.ABFrame
{
    /// <summary>
    /// 缓存对象
    /// </summary>
    public class CacheObject
    {
        public uint crc;
        public string path;
        public int insid;
        public GameObject obj;
        public void Release()
        {
            crc = 0;
            insid = 0;
            path = "";
            obj = null;
        }
    }


    public class ResourcesManager : IResourcesInterface
    {
        //已经加载过的资源字典 key 为路径  value 为资源对象
        private Dictionary<uint, BundleItem> mAlreayLoadAssetsDic = new Dictionary<uint, BundleItem>();

        //对象池字典
        private Dictionary<uint, List<CacheObject>> mObjectPoolDic = new Dictionary<uint, List<CacheObject>>();

        //所有对象字典
        private Dictionary<int, CacheObject> mAllObjectDic = new Dictionary<int, CacheObject>();
        //缓存对象类对象池
        private ClassObjectPool<CacheObject> mCacheObjectPool = new ClassObjectPool<CacheObject>(200);

        //每个资源路径的活跃实例计数（在场景中 + 在对象池中），为0时才卸载AssetBundle
        private Dictionary<uint, int> mActiveInstanceCountDic = new Dictionary<uint, int>();

        //任务加载异步列表
        private List<long> mAsyncLoadingTaskList = new List<long>();
        //异步加载任务唯一id
        private long asyncGuid;
        /// <summary>
        /// 异步加载任务唯一id
        /// </summary>
        private long mAsyncTaskGuid
        {
            get
            {
                if (asyncGuid > long.MaxValue)
                    asyncGuid = 0;
                return asyncGuid++;
            }
        }


        private Dictionary<uint, UniTaskCompletionSource> mWaitDownloadTcs = new Dictionary<uint, UniTaskCompletionSource>();

        //等待加载的资源列表
        private List<HotFileInfo> mWaitLoadAndCloneAssetsList = new List<HotFileInfo>();

        public void Initlizate()
        {
            HotAssetsManager.DownLoadBundleFinish += AssetsDownLoadFinish;
        }


        #region 对象加载
        /// <summary>
        /// AB包资源下载完成回调
        /// </summary>
        /// <param name="info"></param>
        private void AssetsDownLoadFinish(HotFileInfo info)
        {
            //处理比配置文件先下载的ab包
            if (info.abName.Contains("bundleconfig"))
            {
                Debug.Log("Handler waitLoadList Count:" + mWaitLoadAndCloneAssetsList.Count);
                HotFileInfo[] hotFileArray = mWaitLoadAndCloneAssetsList.ToArray();
                mWaitLoadAndCloneAssetsList.Clear();
                foreach (var item in hotFileArray)
                {
                    AssetsDownLoadFinish(item);
                }
                return;
            }

            if (mWaitDownloadTcs.Count > 0)
            {
                //从这个ab包中得到这个包中所有的文件信息
                List<BundleItem> assetsItemLsit = AssetBundleManager.Instance.GetBundleItemByAbName(info.abName);
                //如果长度为0 说明配置文件没有加载
                //由于资源下载是多线程下载，会出现assetbundle下载速度大于配置文件下载速度
                if (assetsItemLsit.Count == 0)
                {
                    for (int i = 0; i < mWaitLoadAndCloneAssetsList.Count; i++)
                    {
                        if (mWaitLoadAndCloneAssetsList[i].abName == info.abName)
                            return;
                    }
                    mWaitLoadAndCloneAssetsList.Add(info);
                    return;
                }
                else
                {
                    uint crc = 0;

                    for (int i = 0; i < assetsItemLsit.Count; i++)
                    {
                        crc = Crc32.GetCrc32(assetsItemLsit[i].path);
                        if (mWaitDownloadTcs.ContainsKey(crc))
                        {
                            mWaitDownloadTcs[crc].TrySetResult();
                            Debug.Log("ResourcesManager AssetsDownLoadFinish Load obj path:" + assetsItemLsit[i].path);
                        }
                    }
                }
            }
        }

        #region 同步克隆物体重载
        /// <summary>
        /// 同步克隆物体
        /// </summary>
        /// <param name="path"></param>
        /// <param name="parent"></param>
        /// <param name="localPosition"></param>
        /// <param name="localScale"></param>
        /// <param name="quateraion"></param>
        /// <returns></returns>

        /// <summary>
        /// 同步克隆物体
        /// </summary>
        /// <param name="path"></param>
        /// <param name="parent"></param>
        /// <param name="localPosition"></param>
        /// <param name="localScale"></param>
        /// <param name="quateraion"></param>
        /// <returns></returns>
        public GameObject Instantiate(string path)
        {
            return Instantiate(path, null);
        }
        public GameObject Instantiate(string path, Transform parent)
        {
            return Instantiate(path, parent, Vector3.zero);
        }
        public GameObject Instantiate(string path, Transform parent, Vector3 localPosition)
        {
            return Instantiate(path, parent, localPosition, Vector3.one);
        }
        public GameObject Instantiate(string path, Transform parent, Vector3 localPosition, Vector3 localScale)
        {
            return Instantiate(path, parent, localPosition, localScale, Quaternion.identity);
        }
        public GameObject Instantiate(string path, Transform parent, Vector3 localPosition, Vector3 localScale, Quaternion quateraion)
        {
            path = path.EndsWith(".prefab") ? path : path + ".prefab";
            //先从对象池查找对象
            GameObject chacheObj = GetCacheObjectFromPools(Crc32.GetCrc32(path));
            if (chacheObj != null)
            {
                chacheObj.transform.SetParent(parent);
                chacheObj.transform.localPosition = localPosition;
                chacheObj.transform.localScale = localScale;
                chacheObj.transform.rotation = quateraion;
                return chacheObj;
            }
            else
            {
                //加载该对象
                GameObject obj = LoadResource<GameObject>(path);
                if (obj != null)
                {
                    GameObject nObj = InstantiateClone(path, obj, parent);
                    nObj.transform.localPosition = localPosition;
                    nObj.transform.localScale = localScale;
                    nObj.transform.rotation = quateraion;
                    return nObj;
                }

            }
            Debug.LogError("GameObject Load failed ,path is null ...");
            return null;
        }
        #endregion
        /// <summary>
        /// 克隆一个对象
        /// </summary>
        /// <param name="path"></param>
        /// <param name="obj"></param>
        /// <param name="parent"></param>
        /// <returns></returns>
        private GameObject InstantiateClone(string path, GameObject obj, Transform parent)
        {
            obj = GameObject.Instantiate(obj, parent, false);
            CacheObject cacheObject = mCacheObjectPool.Spawn();
            cacheObject.obj = obj;
            cacheObject.path = path;
            cacheObject.crc = Crc32.GetCrc32(path);
            cacheObject.insid = obj.GetInstanceID();
            mAllObjectDic.Add(cacheObject.insid, cacheObject);

            //增加克隆物体在场景中的计数 用来卸载ab包
            uint crc = cacheObject.crc;
            if (mActiveInstanceCountDic.ContainsKey(crc))
                mActiveInstanceCountDic[crc]++;
            else
                mActiveInstanceCountDic.Add(crc, 1);
            return obj;
        }

        /// <summary>
        /// 异步克隆物体
        /// </summary> 
        /// <param name="path">路径</param>
        /// <param name="loadAsync">加载回调</param>
        /// <param name="param1">加载参数</param>
        /// <param name="param2">加载参数2</param>
        public async UniTask<GameObject> InstantiateAsync(string path)
        {
            path = path.EndsWith(".prefab") ? path : path + ".prefab";
            //先从对象池查找对象
            GameObject cacheObj = GetCacheObjectFromPools(Crc32.GetCrc32(path));
            if (cacheObj != null)
            {
                return cacheObj;
            }
            //获取异步加载任务唯一id
            long guid = mAsyncTaskGuid;
            mAsyncLoadingTaskList.Add(guid);
            //开始异步加载
            GameObject obj = await LoadResourceAsync<GameObject>(path);
            if (obj != null)
            {
                if (mAsyncLoadingTaskList.Contains(guid))
                {
                    mAsyncLoadingTaskList.Remove(guid);
                    GameObject nObj = InstantiateClone(path, obj, null);
                    return nObj;
                }
                Debug.LogError("Async Load GameObject Command be remover:" + path);
                return null;
            }
            mAsyncLoadingTaskList.Remove(guid);
            return null;
        }

        /// <summary>
        /// 克隆并且等待资源下载完成
        /// </summary>
        /// <param name="path"></param>
        /// <returns></returns>
        public async UniTask<GameObject> InstantiateAndLoadAsync(string path)
        {
            path = path.EndsWith(".prefab") ? path : path + ".prefab";
            uint crc = Crc32.GetCrc32(path);
            //先从对象池查找对象
            GameObject cacheObj = GetCacheObjectFromPools(crc);
            if (cacheObj != null)
            {
                return cacheObj;
            }
            GameObject obj = await InstantiateAsync(path);
            if (obj != null)
            {
                return obj;
            }
            else
            {
                try
                {
                    //如果已经有TCS在等待了，直接复用即可
                    if (mWaitDownloadTcs.TryGetValue(crc, out var exixtingTcs))
                    {
                        await exixtingTcs.Task;
                    }
                    else
                    {
                        var tcs = new UniTaskCompletionSource();
                        mWaitDownloadTcs.Add(crc, tcs);
                        await tcs.Task;
                        mWaitDownloadTcs.Remove(crc);
                    }
                }
                catch (OperationCanceledException)
                {
                    return null;
                }
            }
            obj = await InstantiateAsync(path);
            if (obj != null)
                return obj;

            Debug.LogError("Asset Load Failed is null，path:" + path);
            return null;
        }
        /// <summary>
        /// 从对象池中获取对象
        /// </summary>
        /// <returns></returns>
        private GameObject GetCacheObjectFromPools(uint crc)
        {
            List<CacheObject> objList = null;
            mObjectPoolDic.TryGetValue(crc, out objList);

            if (objList != null && objList.Count > 0)
            {
                //直接取出对象池中第0个
                CacheObject obj = objList[0];
                objList.RemoveAt(0);
                return obj.obj;
            }
            return null;
        }

        /// <summary>
        /// 预加载对象
        /// </summary>
        /// <param name="path"></param>
        /// <param name="count"></param>
        public void PreLoadObj(string path, int count = 1)
        {
            List<GameObject> preLaodObjList = new List<GameObject>();
            for (int i = 0; i < count; i++)
            {
                preLaodObjList.Add(Instantiate(path));
            }
            //回收到对象池
            foreach (var obj in preLaodObjList)
            {
                Release(obj);
            }
        }

        /// <summary>
        /// 预加载资源
        /// </summary>
        /// <typeparam name="T"></typeparam>
        /// <param name="path"></param>
        public void PreLoadResource<T>(string path) where T : UnityEngine.Object
        {
            LoadResource<T>(path);
